#!/usr/bin/env python3
# Generated by runa via A2A Mesh delegation
"""
Git pull diff-alapú skip — csak akkor pull, ha remote-ban van új commit vs local HEAD.
-90% felesleges fetch+checkout a hálózati forgalom és I/O terhelésen.

Ez a modul egy GitPullSkipper osztályt valósít meg, amely:
1. Ellenőrzi a local HEAD és a remote HEAD commit hash-ét (git ls-remote segítségével, fetch nélkül).
2. Csak akkor hajt végre tényleges git fetch+checkout/pull-t, ha a remote újabb commitot tartalmaz.
3. Gyorsítótárazza az eredményt egy rövid TTL-vel, hogy elkerülje a túl gyakori ls-remote hívásokat.
4. Logolja a skip-elt és a végrehajtott pull-okat.
"""

import subprocess
import time
import hashlib
import logging
from dataclasses import dataclass, field
from typing import Optional, Tuple

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s [%(levelname)s] %(name)s: %(message)s",
)
logger = logging.getLogger("git_pull_skipper")


@dataclass
class PullResult:
    """Egy pull/skip művelet eredménye."""
    pulled: bool
    skipped: bool
    local_head: Optional[str] = None
    remote_head: Optional[str] = None
    message: str = ""
    elapsed: float = 0.0


@dataclass
class _CacheEntry:
    remote_head: str
    timestamp: float


class GitPullSkipper:
    """
    Git pull diff-alapú skip implementáció.

    Használat:
        skipper = GitPullSkipper(repo_path=".", branch="main", remote="origin")
        result = skipper.smart_pull()
        if result.pulled:
            print("Új commitok pull-olva.")
        else:
            print("Nincs új commit, skip.")
    """

    def __init__(
        self,
        repo_path: str = ".",
        branch: str = "main",
        remote: str = "origin",
        cache_ttl: float = 10.0,
        fetch_timeout: int = 30,
        ls_remote_timeout: int = 15,
    ):
        self.repo_path = repo_path
        self.branch = branch
        self.remote = remote
        self.cache_ttl = cache_ttl
        self.fetch_timeout = fetch_timeout
        self.ls_remote_timeout = ls_remote_timeout
        self._cache: Optional[_CacheEntry] = None
        # Statisztikák
        self.stats = {
            "total_calls": 0,
            "skipped": 0,
            "pulled": 0,
            "errors": 0,
            "time_saved_sec": 0.0,
        }

    # ------------------------------------------------------------------
    # Belső segédfüggvények
    # ------------------------------------------------------------------

    def _run_git(self, args: list, timeout: int = 30) -> Tuple[int, str, str]:
        """Futtat egy git parancsot és visszaadja (returncode, stdout, stderr)."""
        try:
            proc = subprocess.run(
                ["git"] + args,
                cwd=self.repo_path,
                capture_output=True,
                text=True,
                timeout=timeout,
            )
            return proc.returncode, proc.stdout.strip(), proc.stderr.strip()
        except subprocess.TimeoutExpired:
            return -1, "", f"Timeout after {timeout}s"
        except FileNotFoundError:
            return -1, "", "git binary not found"
        except Exception as exc:
            return -1, "", str(exc)

    def _get_local_head(self) -> Optional[str]:
        """Visszaadja a local HEAD commit hash-ét (rövid formátumban)."""
        rc, out, err = self._run_git(["rev-parse", "HEAD"], timeout=10)
        if rc != 0:
            logger.warning("Nem sikerült lekérdezni a local HEAD-et: %s", err)
            return None
        return out.strip()

    def _get_remote_head(self, use_cache: bool = True) -> Optional[str]:
        """
        Visszaadja a remote HEAD commit hash-ét git ls-remote segítségével (fetch nélkül).
        Ez sokkal olcsóbb, mint egy teljes fetch+checkout.
        """
        if use_cache and self._cache is not None:
            age = time.time() - self._cache.timestamp
            if age < self.cache_ttl:
                logger.debug(
                    "ls-remote cache hit (age=%.1fs, ttl=%.1fs)", age, self.cache_ttl
                )
                return self._cache.remote_head

        # git ls-remote <remote> refs/heads/<branch>
        rc, out, err = self._run_git(
            ["ls-remote", self.remote, f"refs/heads/{self.branch}"],
            timeout=self.ls_remote_timeout,
        )
        if rc != 0:
            logger.warning("ls-remote sikertelen: %s", err or out)
            return None

        # A kimenet formátuma: <hash>\trefs/heads/<branch>
        for line in out.splitlines():
            parts = line.split("\t")
            if len(parts) == 2 and parts[1] == f"refs/heads/{self.branch}":
                remote_head = parts[0].strip()
                self._cache = _CacheEntry(
                    remote_head=remote_head, timestamp=time.time()
                )
                return remote_head

        logger.warning("Nem találtam remote branch ref-et a kimenetben.")
        return None

    def _do_fetch_and_checkout(self) -> bool:
        """
        Tényleges git fetch + checkout/pull végrehajtása.
        Visszatér True-val, ha sikeres volt.
        """
        logger.info("Új commitok észlelve — fetch+checkout indítása...")

        # 1. Fetch
        rc, out, err = self._run_git(
            ["fetch", self.remote, self.branch], timeout=self.fetch_timeout
        )
        if rc != 0:
            logger.error("git fetch sikertelen: %s", err or out)
            return False

        # 2. Reset hard a remote branch-hez (vagy merge)
        # Biztonságosabb: git reset --hard origin/<branch> — feltételezzük, hogy
        # ez egy managed repo, ahol a local módosítások nem kívánatosak.
        rc, out, err = self._run_git(
            ["reset", "--hard", f"{self.remote}/{self.branch}"], timeout=15
        )
        if rc != 0:
            logger.error("git reset --hard sikertelen: %s", err or out)
            return False

        logger.info("Sikeresen frissítve: %s", out)
        return True

    # ------------------------------------------------------------------
    # Nyilvános API
    # ------------------------------------------------------------------

    def smart_pull(self, force: bool = False) -> PullResult:
        """
        Fő metódus: diff-alapú skip-pel pull.

        Args:
            force: Ha True, kihagyja a diff ellenőrzést és mindig pull-t hajt végre.

        Returns:
            PullResult objektum a művelet eredményével.
        """
        start = time.time()
        self.stats["total_calls"] += 1

        local_head = self._get_local_head()
        if local_head is None:
            self.stats["errors"] += 1
            return PullResult(
                pulled=False,
                skipped=False,
                message="Nem sikerült lekérdezni a local HEAD-et.",
                elapsed=time.time() - start,
            )

        if force:
            logger.info("Force pull kérés — diff ellenőrzés kihagyása.")
            success = self._do_fetch_and_checkout()
            elapsed = time.time() - start
            if success:
                self.stats["pulled"] += 1
                new_head = self._get_local_head()
                return PullResult(
                    pulled=True,
                    skipped=False,
                    local_head=local_head,
                    remote_head=new_head,
                    message="Force pull sikeres.",
                    elapsed=elapsed,
                )
            else:
                self.stats["errors"] += 1
                return PullResult(
                    pulled=False,
                    skipped=False,
                    local_head=local_head,
                    message="Force pull sikertelen.",
                    elapsed=elapsed,
                )

        remote_head = self._get_remote_head()
        if remote_head is None:
            self.stats["errors"] += 1
            return PullResult(
                pulled=False,
                skipped=False,
                local_head=local_head,
                message="Nem sikerült lekérdezni a remote HEAD-et.",
                elapsed=time.time() - start,
            )

        # Diff ellenőrzés
        if local_head == remote_head:
            elapsed = time.time() - start
            self.stats["skipped"] += 1
            # Becsült megtakarítás: egy fetch+checkout ~0.5-2s, egy ls-remote ~0.1s
            self.stats["time_saved_sec"] += max(0.0, 0.5 - elapsed)
            logger.info(
                "SKIP — local HEAD (%s) == remote HEAD (%s). Nincs új commit.",
                local_head[:12],
                remote_head[:12],
            )
            return PullResult(
                pulled=False,
                skipped=True,
                local_head=local_head,
                remote_head=remote_head,
                message="Nincs új commit a remote-ban, pull skip-elve.",
                elapsed=elapsed,
            )

        # Van új commit — tényleges pull
        logger.info(
            "DIFF észlelve — local: %s, remote: %s. Pull indítása.",
            local_head[:12],
            remote_head[:12],
        )
        success = self._do_fetch_and_checkout()
        elapsed = time.time() - start

        if success:
            self.stats["pulled"] += 1
            new_head = self._get_local_head()
            return PullResult(
                pulled=True,
                skipped=False,
                local_head=local_head,
                remote_head=remote_head,
                message=f"Sikeres pull: {local_head[:12]} → {new_head[:12] if new_head else '???'}",
                elapsed=elapsed,
            )
        else:
            self.stats["errors"] += 1
            return PullResult(
                pulled=False,
                skipped=False,
                local_head=local_head,
                remote_head=remote_head,
                message="Pull sikertelen.",
                elapsed=elapsed,
            )

    def get_stats(self) -> dict:
        """Visszaadja a futási statisztikákat."""
        total = self.stats["total_calls"]
        skip_rate = (self.stats["skipped"] / total * 100) if total > 0 else 0.0
        return {
            **self.stats,
            "skip_rate_pct": round(skip_rate, 1),
        }

    def reset_cache(self):
        """Törli a ls-remote gyorsítótárat."""
        self._cache = None


# ----------------------------------------------------------------------
# CLI belépési pont
# ----------------------------------------------------------------------

def _parse_args():
    import argparse

    parser = argparse.ArgumentParser(
        description="Git pull diff-alapú skip — csak akkor pull, ha remote-ban van új commit."
    )
    parser.add_argument(
        "--repo", default=".", help="A git repo útvonala (alapértelmezett: jelenlegi könyvtár)."
    )
    parser.add_argument(
        "--branch", default="main", help="A figyelendő branch (alapértelmezett: main)."
    )
    parser.add_argument(
        "--remote", default="origin", help="A remote név (alapértelmezett: origin)."
    )
    parser.add_argument(
        "--cache-ttl", type=float, default=10.0,
        help="ls-remote cache TTL másodpercben (alapértelmezett: 10).",
    )
    parser.add_argument(
        "--force", action="store_true",
        help="Diff ellenőrzés kihagyása — mindig pull.",
    )
    parser.add_argument(
        "--watch", type=float, default=0, metavar="INTERVAL",
        help="Folyamatos figyelés megadott intervallumon (másodperc). 0 = egyszeri futás.",
    )
    parser.add_argument(
        "--stats", action="store_true",
        help="Statisztikák kiírása a futás végén.",
    )
    return parser.parse_args()


def main():
    args = _parse_args()

    skipper = GitPullSkipper(
        repo_path=args.repo,
        branch=args.branch,
        remote=args.remote,
        cache_ttl=args.cache_ttl,
    )

    if args.watch > 0:
        logger.info(
            "Watch mód — ellenőrzés minden %.1f másodpercben. Ctrl+C a leállításhoz.",
            args.watch,
        )
        try:
            while True:
                result = skipper.smart_pull(force=args.force)
                status = "PULLED" if result.pulled else ("SKIPPED" if result.skipped else "ERROR")
                logger.info(
                    "[%s] %s (%.3fs)", status, result.message, result.elapsed
                )
                time.sleep(args.watch)
        except KeyboardInterrupt:
            logger.info("Watch leállítva.")
    else:
        result = skipper.smart_pull(force=args.force)
        status = "PULLED" if result.pulled else ("SKIPPED" if result.skipped else "ERROR")
        print(f"[{status}] {result.message} ({result.elapsed:.3f}s)")
        if result.local_head:
            print(f"  Local HEAD:  {result.local_head}")
        if result.remote_head:
            print(f"  Remote HEAD: {result.remote_head}")

    if args.stats:
        stats = skipper.get_stats()
        print("\n--- Statisztikák ---")
        for key, val in stats.items():
            print(f"  {key}: {val}")


if __name__ == "__main__":
    main()